<?php require 'faculty_bootstrap.php';$title='Enrollment Requests';$fid=(int)$_SESSION['user']['id'];$status=$_GET['status']??'pending';if(!in_array($status,['pending','approved','rejected','all'],true))$status='pending';$sql="SELECT e.*,u.name student,u.student_id,u.program,s.code,s.name subject,s.units,o.day_name,o.start_time,o.end_time,o.room,o.section FROM enrollments e JOIN users u ON u.id=e.student_id JOIN subjects s ON s.id=e.subject_id JOIN subject_offerings o ON o.id=e.offering_id WHERE o.faculty_id=?";$p=[$fid];if($status!=='all'){$sql.=' AND e.status=?';$p[]=$status;}$sql.=' ORDER BY CASE WHEN e.status="pending" THEN 0 ELSE 1 END,e.created_at DESC';$q=$pdo->prepare($sql);$q->execute($p);$rows=$q->fetchAll();require 'header.php';faculty_flash_html();
?><section class="section"><div class="section-intro"><div><span class="eyebrow">ENROLLMENT</span><h2>Enrollment Requests</h2><p class="muted">Review requests for sections assigned to you.</p></div><form method="get" class="announcement-filter"><select name="status"><option value="pending" <?=$status==='pending'?'selected':''?>>Pending</option><option value="approved" <?=$status==='approved'?'selected':''?>>Approved</option><option value="rejected" <?=$status==='rejected'?'selected':''?>>Rejected</option><option value="all" <?=$status==='all'?'selected':''?>>All</option></select><button class="btn">Filter</button></form></div><?php if(!$rows):?><p class="muted">No <?=e($status==='all'?'':' '.$status)?> enrollment requests.</p><?php endif;?><?php foreach($rows as $r):?><div class="faculty-request"><div class="faculty-request-main"><div class="card-head"><div><b><?=e($r['student'])?></b><small class="muted"><?=e($r['student_id']?:'No Student ID')?> · <?=e($r['program']?:'Program not set')?></small></div><span class="badge <?=e($r['status'])?>"><?=ucfirst(e($r['status']))?></span></div><p><b><?=e($r['code'])?> — <?=e($r['subject'])?></b> · <?=e($r['units'])?> units</p><p class="muted"><?=e($r['day_name'])?> · <?=date('g:i A',strtotime($r['start_time']))?>–<?=date('g:i A',strtotime($r['end_time']))?> · Section <?=e($r['section'])?> · <?=e($r['room'])?></p><small class="muted">Requested <?=date('M d, Y · g:i A',strtotime($r['created_at']))?></small></div><?php if($r['status']==='pending'):?><form method="post" class="button-group faculty-request-actions"><?=faculty_form_return('faculty_enrollment.php')?><input type="hidden" name="action" value="faculty_enrollment_action"><input type="hidden" name="enrollment_id" value="<?=$r['id']?>"><button class="btn" name="status" value="approved">Approve</button><button class="btn danger-btn" name="status" value="rejected">Reject</button></form><?php endif;?></div><?php endforeach;?></section><?php require 'footer.php';?>
